export interface ResolvedRoute<T extends string = string> {
  /** Space-relative document path: leading '/', no trailing '/'. '/' at the Space root. */
  path: string
  /** The routed `pages` collection key for this (Tenant, Space). */
  pagesKey: PagesKeyOf<T>
  /** Every non-`pages` collection in the Space, keyed by Collection name → generated
   *  key — the Space-landing collection index reads `Object.entries(collections)`. */
  collections: CollectionsOf<T>
  /** True when the request targets the Space root ('/'). */
  atRoot: boolean
}

/** The canonical ADR-0006 route for a Document: `/t/<tenant>/<space>` plus its
 *  Space-relative `path` ('/' at the Space root). Single-homes the URL scheme so
 *  a cross-Tenant aggregator (`queryAcrossTenants`, ADR-0025) links back to a
 *  page's real route instead of inventing a `/dollhouse/`-style one — the catalog
 *  composing with routing, exactly as issue #642 intends. */
export function documentUrl(tenant: string, space: string, path: string): string {
  return `/t/${tenant}/${space}${path === '/' ? '' : path}`
}

