 *  it always processes every file it's given, so both stay unconditionally
 *  credited the way `cat`/`sed` already are. */
const READER_VERBS = new Set(['cat', 'bat', 'sed', 'head', 'tail', 'awk', 'grep', 'rg', 'less', 'more', 'diff'])

/** A glob/variable token that would be in scope if it named one literal file —
 *  reported as a near-miss so an unresolvable read is visible rather than silent. */
function isGlobbedInstructionDoc(path: string): boolean {
  if (!GLOB_OR_VAR.test(path)) return false
  const literal = path.replace(new RegExp(GLOB_OR_VAR.source, 'g'), 'x')
  // An extensionless glob (`docs/adr/0003*`) can still resolve to a `.md` doc.
  return isInstructionDoc(literal) || isInstructionDoc(`${literal}.md`)
}

/** `quoted` is load-bearing, not bookkeeping: every flag rule below must ignore a
 *  token that only LOOKS like a flag because a pattern was quoted. Without it
 *  `grep -rn "-l" docs/x.md` reads as a names-only grep and the doc is lost. */
interface Token {
  text: string
  quoted: boolean
}

/** Every file a Bash command's reader verbs name, as absolute paths, for
 *  scripts/bash-rules-hint.ts (issue #1764). Any file, not only instruction
 *  docs. `simple` marks the one-file read Claude Code already loads rules for
 *  (ADR-0029). After a `cd` the parser cannot follow, relative paths drop. */
export function bashReadPaths(command: string, cwd: string): { paths: string[]; simple: boolean } {
  const segs = segments(command)
  const paths: string[] = []
  let dir: string | undefined = cwd
  let simple = false
  for (const seg of segs) {
    const tokens = unwrap(seg.tokens)
    const verb = tokens[0]?.text.replace(/^.*\//, '') ?? ''
    if (verb === 'cd') {
      const to = tokens[1]?.text
      dir = dir && to && to !== '-' && !GLOB_OR_VAR.test(to) ? resolve(dir, to) : undefined
      continue

      const text = a.text.replace(/^</, '')
      if (a.skip || !text) continue
      files++
      if (GLOB_OR_VAR.test(text) || !(dir || isAbsolute(text))) continue
      // A trailing `/` marks a directory for the hint; resolve() would drop it.
      paths.push(resolve(dir ?? '/', text) + (text.endsWith('/') ? '/' : ''))
    }
    simple = segs.length === 1 && tokens.length === seg.tokens.length && files === 1
  }
  return { paths: [...new Set(paths)], simple }
}

